-- a2.1 reading: 8 rewritten lessons get auto-checkable
-- "checks" items (Richtig/Falsch and exam-style choice) plus 2 brand-new
-- exam-format lessons. Course Factory content pipeline.
--
-- Generated by scripts/reading-from-json.mjs from the reviewed JSON — do not
-- hand-edit; regenerate instead. Idempotent: every UPDATE is guarded by
-- `AND checks IS NULL` (a no-op once applied) and every INSERT by
-- `WHERE NOT EXISTS` on (level, title_de).
--
-- How to test: apply by hand in the Supabase SQL editor, then:
--   SELECT id, title_de, jsonb_array_length(checks) FROM public.reading_lessons
--   WHERE level = 'a2.1' ORDER BY order_index;
-- should show 10 rows, all with a non-null `checks` array (the rewrites keep
-- their reviewed check count, the new exam-format lessons carry theirs).
-- Rollback: `UPDATE public.reading_lessons SET checks = NULL WHERE id IN (...)`
-- for the 8 ids above, and `DELETE ... WHERE level = 'a2.1' AND title_de IN
-- ('Lesen Teil 1: Ein Zeitungstext (wie in der Prüfung)', 'Lesen Teil 3: Eine E-Mail (wie in der Prüfung)')`
-- for the 2 inserts. The ADD COLUMN is left in place (a null column is inert).

BEGIN;

ALTER TABLE public.reading_lessons ADD COLUMN IF NOT EXISTS checks jsonb;

-- ---------------------------------------------------------------------------
-- Rewrites (8 rows, guarded by id + checks IS NULL)
-- ---------------------------------------------------------------------------

UPDATE public.reading_lessons SET
  title_de = 'Meine Reise nach Wien',
  title_en = 'My Trip to Vienna',
  content_de = 'Letzten Monat habe ich eine Reise nach Wien gemacht. Wien ist die Hauptstadt von Österreich. Ich bin mit dem Zug gefahren, weil ich gern Zug fahre. Die Fahrt von München nach Wien hat vier Stunden gedauert.

Im Zug hatte ich einen Platz am Fenster. Ich habe ein Buch gelesen und Kaffee getrunken.

In Wien habe ich in einem kleinen Hotel im Zentrum übernachtet. Das Hotel war nicht teuer. Von dort konnte ich alles zu Fuß erreichen. Am ersten Tag bin ich die Ringstraße entlanggegangen.

Am zweiten Tag habe ich das Schloss Schönbrunn besucht. Der große Garten hat mir sehr gut gefallen.

Am Abend habe ich ein Wiener Schnitzel gegessen. Zum Nachtisch habe ich Sachertorte probiert. In einem Kaffeehaus habe ich noch eine Melange getrunken.

Nach vier Tagen bin ich wieder nach Hause gefahren.',
  content_en = 'Last month I took a trip to Vienna. Vienna is the capital of Austria. I went by train, because I like going by train. The journey from Munich to Vienna took four hours.

On the train I had a seat by the window. I read a book and drank coffee.

In Vienna I stayed in a small hotel in the centre. The hotel was not expensive. From there I could reach everything on foot. On the first day I walked along the Ringstraße.

On the second day I visited Schönbrunn Palace. I liked the big garden very much.

In the evening I ate a Wiener Schnitzel. For dessert I tried Sachertorte. In a coffee house I also drank a Melange.

After four days I travelled back home.',
  key_vocabulary = '[{"de":"die Reise, -n","en":"trip, journey"},{"de":"die Hauptstadt, ¨-e","en":"capital city"},{"de":"der Zug, ¨-e","en":"train"},{"de":"die Fahrt, -en","en":"journey, ride"},{"de":"dauern","en":"to last, to take (time)"},{"de":"der Platz, ¨-e","en":"seat, place"},{"de":"übernachten","en":"to stay overnight"},{"de":"das Zentrum, Zentren","en":"centre"},{"de":"erreichen","en":"to reach"},{"de":"das Schloss, ¨-er","en":"palace, castle"},{"de":"der Garten, ¨-","en":"garden"},{"de":"gefallen (+ Dat.)","en":"to please, to be liked by"},{"de":"der Nachtisch, -e","en":"dessert"},{"de":"probieren","en":"to try, to taste"}]'::jsonb,
  questions = '[{"question_de":"Wann hat die Person die Reise gemacht?","question_en":"When did the person take the trip?","answer_de":"Sie hat die Reise letzten Monat gemacht.","answer_en":"The person took the trip last month."},{"question_de":"Was hat die Person im Zug gemacht?","question_en":"What did the person do on the train?","answer_de":"Sie hat ein Buch gelesen und Kaffee getrunken.","answer_en":"The person read a book and drank coffee."},{"question_de":"Was hat der Person im Schloss Schönbrunn gut gefallen?","question_en":"What did the person like at Schönbrunn Palace?","answer_de":"Der große Garten hat ihr sehr gut gefallen.","answer_en":"The person liked the big garden very much."},{"question_de":"Was hat die Person am Abend gegessen?","question_en":"What did the person eat in the evening?","answer_de":"Sie hat ein Wiener Schnitzel gegessen.","answer_en":"The person ate a Wiener Schnitzel."},{"question_de":"Wie lange war die Person in Wien?","question_en":"How long was the person in Vienna?","answer_de":"Sie war vier Tage in Wien.","answer_en":"The person was in Vienna for four days."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person ist mit dem Zug nach Wien gefahren.","statement_en":"The person went to Vienna by train.","answer":"richtig","explanation_de":"Im Text steht: Ich bin mit dem Zug gefahren."},{"type":"rf","statement_de":"Die Person hat bei Freunden übernachtet.","statement_en":"The person stayed with friends.","answer":"falsch","explanation_de":"Im Text steht: In Wien habe ich in einem kleinen Hotel im Zentrum übernachtet."},{"type":"rf","statement_de":"Im Zug hatte die Person einen Platz am Gang.","statement_en":"On the train the person had an aisle seat.","answer":"falsch","explanation_de":"Im Text steht: Im Zug hatte ich einen Platz am Fenster."},{"type":"rf","statement_de":"Die Person konnte alles zu Fuß erreichen.","statement_en":"The person could reach everything on foot.","answer":"richtig","explanation_de":"Im Text steht: Von dort konnte ich alles zu Fuß erreichen."},{"type":"rf","statement_de":"Die Person hat in einem Kaffeehaus eine Melange getrunken.","statement_en":"The person drank a Melange in a coffee house.","answer":"richtig","explanation_de":"Im Text steht: In einem Kaffeehaus habe ich noch eine Melange getrunken."},{"type":"choice","statement_de":"Wie lange hat die Fahrt gedauert? a) zwei Stunden b) vier Stunden c) sechs Stunden","statement_en":"How long did the journey take? a) two hours b) four hours c) six hours","options":["a","b","c"],"answer":"b","explanation_de":"Im Text steht: Die Fahrt von München nach Wien hat vier Stunden gedauert."}]'::jsonb,
  word_count = 133,
  estimated_reading_time = 2
WHERE id = 'a94a8a40-c8a6-4bed-bd79-a8b4dd9e05f8'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Beim Arzt',
  title_en = 'At the Doctor',
  content_de = 'Letzte Woche war ich krank. Ich hatte Kopfschmerzen, Halsschmerzen und Fieber. Nach zwei Tagen bin ich zum Arzt gegangen.

In der Praxis musste ich zuerst zur Anmeldung gehen. Dort habe ich meine Karte gezeigt. Dann habe ich im Wartezimmer gewartet. Das Wartezimmer war voll. Nach dreißig Minuten konnte ich ins Sprechzimmer gehen.

Die Ärztin war sehr freundlich. Ich habe ihr meine Probleme beschrieben. Sie hat mich untersucht und meine Temperatur gemessen: 38,5 Grad.

Danach hat sie mir die Diagnose erklärt. Ich hatte eine starke Erkältung. Zum Glück war es nicht schlimm.

Die Ärztin hat mir ein Rezept gegeben. Ich soll dreimal am Tag eine Tablette nehmen. Ich soll auch viel Tee trinken. Bis Freitag darf ich nicht arbeiten.

Nach dem Termin bin ich in die Apotheke gegangen. Dort habe ich meine Medikamente geholt.',
  content_en = 'Last week I was ill. I had a headache, a sore throat and a fever. After two days I went to the doctor.

At the practice I first had to go to the reception. There I showed my card. Then I waited in the waiting room. The waiting room was full. After thirty minutes I could go into the consulting room.

The doctor was very friendly. I described my problems to her. She examined me and measured my temperature: 38.5 degrees.

Afterwards she explained the diagnosis to me. I had a bad cold. Luckily it was not serious.

The doctor gave me a prescription. I am supposed to take one tablet three times a day. I am also supposed to drink a lot of tea. Until Friday I am not allowed to work.

After the appointment I went to the pharmacy. There I picked up my medicine.',
  key_vocabulary = '[{"de":"der Arzt, ¨-e / die Ärztin, -nen","en":"doctor"},{"de":"die Praxis, Praxen","en":"doctor''s practice"},{"de":"die Anmeldung, -en","en":"reception, registration desk"},{"de":"das Wartezimmer, -","en":"waiting room"},{"de":"krank","en":"ill, sick"},{"de":"die Kopfschmerzen (Pl.)","en":"headache"},{"de":"das Fieber","en":"fever"},{"de":"untersuchen","en":"to examine"},{"de":"messen","en":"to measure"},{"de":"die Erkältung, -en","en":"cold (illness)"},{"de":"das Rezept, -e","en":"prescription"},{"de":"die Tablette, -n","en":"tablet, pill"},{"de":"die Apotheke, -n","en":"pharmacy"},{"de":"das Medikament, -e","en":"medicine"}]'::jsonb,
  questions = '[{"question_de":"Welche Probleme hatte die Person?","question_en":"What problems did the person have?","answer_de":"Sie hatte Kopfschmerzen, Halsschmerzen und Fieber.","answer_en":"The person had a headache, a sore throat and a fever."},{"question_de":"Was hat die Person an der Anmeldung gemacht?","question_en":"What did the person do at the reception?","answer_de":"Sie hat dort ihre Karte gezeigt.","answer_en":"The person showed the card there."},{"question_de":"Wie war die Ärztin?","question_en":"What was the doctor like?","answer_de":"Die Ärztin war sehr freundlich.","answer_en":"The doctor was very friendly."},{"question_de":"Was für eine Krankheit hatte die Person?","question_en":"What illness did the person have?","answer_de":"Sie hatte eine starke Erkältung.","answer_en":"The person had a bad cold."},{"question_de":"Was hat die Ärztin der Person gegeben?","question_en":"What did the doctor give the person?","answer_de":"Sie hat ihr ein Rezept gegeben.","answer_en":"The person gave the person a prescription."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person ist am ersten Tag zum Arzt gegangen.","statement_en":"The person went to the doctor on the first day.","answer":"falsch","explanation_de":"Im Text steht: Nach zwei Tagen bin ich zum Arzt gegangen."},{"type":"rf","statement_de":"Die Person hat dreißig Minuten gewartet.","statement_en":"The person waited for thirty minutes.","answer":"richtig","explanation_de":"Im Text steht: Nach dreißig Minuten konnte ich ins Sprechzimmer gehen."},{"type":"rf","statement_de":"Die Ärztin hat die Temperatur gemessen.","statement_en":"The doctor measured the temperature.","answer":"richtig","explanation_de":"Im Text steht: Sie hat mich untersucht und meine Temperatur gemessen."},{"type":"rf","statement_de":"Die Person soll viel Tee trinken.","statement_en":"The person is supposed to drink a lot of tea.","answer":"richtig","explanation_de":"Im Text steht: Ich soll auch viel Tee trinken."},{"type":"rf","statement_de":"Die Person hat die Medikamente im Supermarkt geholt.","statement_en":"The person picked up the medicine at the supermarket.","answer":"falsch","explanation_de":"Im Text steht: Nach dem Termin bin ich in die Apotheke gegangen. Dort habe ich meine Medikamente geholt."},{"type":"choice","statement_de":"Wie hoch war das Fieber? a) 37,5 Grad b) 38,0 Grad c) 38,5 Grad","statement_en":"How high was the fever? a) 37.5 degrees b) 38.0 degrees c) 38.5 degrees","options":["a","b","c"],"answer":"c","explanation_de":"Im Text steht: Sie hat mich untersucht und meine Temperatur gemessen: 38,5 Grad."}]'::jsonb,
  word_count = 133,
  estimated_reading_time = 2
WHERE id = 'b3adfa93-d0f8-4c4f-851b-b161875fb5a3'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Mein Beruf als Softwareentwickler',
  title_en = 'My Job as a Software Developer',
  content_de = 'Ich arbeite als Softwareentwickler bei einer IT-Firma in Hamburg. Schon in der Schule habe ich gern am Computer gearbeitet. Später habe ich Informatik studiert.

Mein Arbeitstag beginnt um neun Uhr. Ich fahre mit dem Fahrrad ins Büro. Die Fahrt dauert nur fünfzehn Minuten.

Im Büro sitze ich mit meinem Team in einem großen Raum. Wir sind fünf Entwickler. Jeden Morgen haben wir ein kurzes Meeting. Dort besprechen wir unsere Aufgaben für den Tag.

Meine Hauptaufgabe ist die Arbeit am Code. Ich entwickle Programme für unsere Kunden. Manchmal muss ich ein schwieriges Problem lösen.

Von halb eins bis halb zwei mache ich Mittagspause. Oft gehe ich mit den Kollegen essen.

Um 18 Uhr ist Feierabend. Zweimal pro Woche darf ich von zu Hause arbeiten. Ich bin sehr zufrieden mit meinem Beruf.',
  content_en = 'I work as a software developer at an IT company in Hamburg. Even at school I liked working at the computer. Later I studied computer science.

My working day starts at nine o''clock. I ride my bicycle to the office. The ride only takes fifteen minutes.

In the office I sit with my team in a big room. There are five of us developers. Every morning we have a short meeting. There we discuss our tasks for the day.

My main task is working on the code. I develop programs for our customers. Sometimes I have to solve a difficult problem.

From half past twelve until half past one I take my lunch break. I often go out to eat with my colleagues.

At six p.m. the working day is over. Twice a week I am allowed to work from home. I am very happy with my job.',
  key_vocabulary = '[{"de":"der Beruf, -e","en":"profession, job"},{"de":"die Firma, Firmen","en":"company"},{"de":"der Arbeitstag, -e","en":"working day"},{"de":"das Büro, -s","en":"office"},{"de":"das Team, -s","en":"team"},{"de":"der Entwickler, -","en":"developer"},{"de":"das Meeting, -s","en":"meeting"},{"de":"besprechen","en":"to discuss"},{"de":"die Aufgabe, -n","en":"task"},{"de":"der Kunde, -n","en":"customer"},{"de":"lösen","en":"to solve"},{"de":"die Mittagspause, -n","en":"lunch break"},{"de":"der Kollege, -n / die Kollegin, -nen","en":"colleague"},{"de":"der Feierabend","en":"end of the working day"}]'::jsonb,
  questions = '[{"question_de":"Wo arbeitet die Person?","question_en":"Where does the person work?","answer_de":"Sie arbeitet bei einer IT-Firma in Hamburg.","answer_en":"The person works at an IT company in Hamburg."},{"question_de":"Was hat die Person studiert?","question_en":"What did the person study?","answer_de":"Sie hat Informatik studiert.","answer_en":"The person studied computer science."},{"question_de":"Was machen die Kollegen jeden Morgen?","question_en":"What do the colleagues do every morning?","answer_de":"Sie haben jeden Morgen ein kurzes Meeting.","answer_en":"Every morning they have a short meeting."},{"question_de":"Was ist ihre Hauptaufgabe?","question_en":"What is her main task?","answer_de":"Ihre Hauptaufgabe ist die Arbeit am Code.","answer_en":"The main task is working on the code."},{"question_de":"Wann ist Feierabend?","question_en":"When does the working day end?","answer_de":"Um 18 Uhr ist Feierabend.","answer_en":"The working day ends at six p.m."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Fahrt ins Büro dauert fünfzehn Minuten.","statement_en":"The ride to the office takes fifteen minutes.","answer":"richtig","explanation_de":"Im Text steht: Die Fahrt dauert nur fünfzehn Minuten."},{"type":"rf","statement_de":"Der Arbeitstag beginnt um neun Uhr.","statement_en":"The working day starts at nine o''clock.","answer":"richtig","explanation_de":"Im Text steht: Mein Arbeitstag beginnt um neun Uhr."},{"type":"rf","statement_de":"Im Team sind acht Entwickler.","statement_en":"There are eight developers in the team.","answer":"falsch","explanation_de":"Im Text steht: Wir sind fünf Entwickler."},{"type":"rf","statement_de":"Die Mittagspause beginnt um zwölf Uhr.","statement_en":"The lunch break starts at twelve o''clock.","answer":"falsch","explanation_de":"Im Text steht: Von halb eins bis halb zwei mache ich Mittagspause."},{"type":"rf","statement_de":"Zweimal pro Woche darf die Person zu Hause arbeiten.","statement_en":"Twice a week the person is allowed to work at home.","answer":"richtig","explanation_de":"Im Text steht: Zweimal pro Woche darf ich von zu Hause arbeiten."},{"type":"choice","statement_de":"Wie kommt die Person ins Büro? a) mit dem Fahrrad b) mit dem Bus c) zu Fuß","statement_en":"How does the person get to the office? a) by bicycle b) by bus c) on foot","options":["a","b","c"],"answer":"a","explanation_de":"Im Text steht: Ich fahre mit dem Fahrrad ins Büro."}]'::jsonb,
  word_count = 130,
  estimated_reading_time = 2
WHERE id = '2625a371-4cc2-4a9e-b941-1a75c7eda792'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Unterwegs in der Stadt',
  title_en = 'Getting Around in the City',
  content_de = 'Ich wohne seit fünf Jahren in Berlin. Am Anfang musste ich oft nach dem Weg fragen. Hier gibt es viele Verkehrsmittel. Meistens fahre ich mit der U-Bahn.

Mein Monatsticket kostet etwa 86 Euro. Damit kann ich jeden Tag fahren. Die U-Bahn ist schnell, denn sie fährt unter der Erde. Die Fahrt zur Arbeit dauert nur zwanzig Minuten. Am Morgen ist die U-Bahn oft sehr voll.

Im Sommer nehme ich oft mein altes Fahrrad. In Berlin gibt es viele Fahrradwege.

Manchmal fahre ich auch mit dem Bus. Aus dem Bus kann man die Straßen und die Parks sehen. Bei viel Verkehr ist der Bus aber langsam.

Ein Auto habe ich nicht. Parkplätze sind teuer, und es gibt oft Stau. Zum Bäcker und zum Supermarkt gehe ich zu Fuß.

Ich bin sehr zufrieden mit den Verkehrsmitteln in Berlin. Man kommt hier überall schnell hin.',
  content_en = 'I have been living in Berlin for five years. At the beginning I often had to ask for directions. There are many means of transport here. Usually I take the underground.

My monthly ticket costs about 86 euros. With it I can travel every day. The underground is fast, because it runs below ground. The trip to work only takes twenty minutes. In the morning the underground is often very full.

In summer I often take my old bicycle. In Berlin there are many cycle paths.

Sometimes I also take the bus. From the bus you can see the streets and the parks. But when there is a lot of traffic, the bus is slow.

I do not have a car. Parking spaces are expensive, and there are often traffic jams. To the baker''s and to the supermarket I walk.

I am very happy with the means of transport in Berlin. You get everywhere quickly here.',
  key_vocabulary = '[{"de":"das Verkehrsmittel, -","en":"means of transport"},{"de":"die U-Bahn, -en","en":"underground, subway"},{"de":"das Monatsticket, -s","en":"monthly ticket"},{"de":"die Fahrt, -en","en":"trip, ride"},{"de":"voll","en":"full, crowded"},{"de":"das Fahrrad, ¨-er","en":"bicycle"},{"de":"der Fahrradweg, -e","en":"cycle path"},{"de":"der Bus, -se","en":"bus"},{"de":"der Verkehr","en":"traffic"},{"de":"der Parkplatz, ¨-e","en":"parking space"},{"de":"der Stau, -s","en":"traffic jam"},{"de":"zu Fuß gehen","en":"to walk, to go on foot"},{"de":"zufrieden","en":"satisfied, happy"}]'::jsonb,
  questions = '[{"question_de":"Womit fährt die Person meistens?","question_en":"What does the person usually travel by?","answer_de":"Sie fährt meistens mit der U-Bahn.","answer_en":"The person usually travels by underground."},{"question_de":"Wann nimmt die Person oft das Fahrrad?","question_en":"When does the person often take the bicycle?","answer_de":"Im Sommer nimmt sie oft ihr Fahrrad.","answer_en":"In summer the person often takes the bicycle."},{"question_de":"Was kann man aus dem Bus sehen?","question_en":"What can you see from the bus?","answer_de":"Man kann die Straßen und die Parks sehen.","answer_en":"You can see the streets and the parks."},{"question_de":"Wie sind die Parkplätze in Berlin?","question_en":"What are parking spaces like in Berlin?","answer_de":"Die Parkplätze sind teuer.","answer_en":"Parking spaces are expensive."},{"question_de":"Wohin geht die Person zu Fuß?","question_en":"Where does the person walk to?","answer_de":"Sie geht zum Bäcker und zum Supermarkt zu Fuß.","answer_en":"The person walks to the baker''s and to the supermarket."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person wohnt seit zehn Jahren in Berlin.","statement_en":"The person has been living in Berlin for ten years.","answer":"falsch","explanation_de":"Im Text steht: Ich wohne seit fünf Jahren in Berlin."},{"type":"rf","statement_de":"Die U-Bahn fährt über der Erde.","statement_en":"The underground runs above ground.","answer":"falsch","explanation_de":"Im Text steht: Die U-Bahn ist schnell, denn sie fährt unter der Erde."},{"type":"rf","statement_de":"Die Fahrt zur Arbeit dauert zwanzig Minuten.","statement_en":"The trip to work takes twenty minutes.","answer":"richtig","explanation_de":"Im Text steht: Die Fahrt zur Arbeit dauert nur zwanzig Minuten."},{"type":"rf","statement_de":"Die Person hat kein Auto.","statement_en":"The person does not have a car.","answer":"richtig","explanation_de":"Im Text steht: Ein Auto habe ich nicht."},{"type":"rf","statement_de":"Am Morgen ist die U-Bahn meistens leer.","statement_en":"In the morning the underground is mostly empty.","answer":"falsch","explanation_de":"Im Text steht: Am Morgen ist die U-Bahn oft sehr voll."},{"type":"choice","statement_de":"Was kostet das Monatsticket ungefähr? a) 68 Euro b) 76 Euro c) 86 Euro","statement_en":"About what does the monthly ticket cost? a) 68 euros b) 76 euros c) 86 euros","options":["a","b","c"],"answer":"c","explanation_de":"Im Text steht: Mein Monatsticket kostet etwa 86 Euro."}]'::jsonb,
  word_count = 142,
  estimated_reading_time = 3
WHERE id = 'a1a4b941-81b1-4e42-b8a7-5afb2863f91a'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Ein Abend im Restaurant',
  title_en = 'An Evening at the Restaurant',
  content_de = 'Letzten Samstag habe ich mit meiner Freundin in einem italienischen Restaurant gegessen. Sie hatte Geburtstag. Ich wollte sie zu einem besonderen Abendessen einladen. Ich habe vorher einen Tisch reserviert.

Um sieben Uhr sind wir angekommen. Der Kellner hat uns einen Platz am Fenster gegeben. Die Musik war leise. Auf den Tischen waren Kerzen.

Zuerst hat uns der Kellner die Speisekarte gebracht. Ich habe einen Rotwein bestellt, meine Freundin ein Mineralwasser.

Als Vorspeise haben wir Bruschetta gegessen. Danach habe ich Spaghetti bestellt und meine Freundin eine Pizza. Die Portionen waren groß, und alles hat sehr gut geschmeckt.

Zum Nachtisch habe ich Tiramisu genommen. Dann haben wir noch einen Espresso getrunken.

Das Essen hat 75 Euro gekostet. Ich habe mit Karte bezahlt und dem Kellner zehn Euro Trinkgeld gegeben. Meine Freundin war sehr glücklich.',
  content_en = 'Last Saturday I ate with my girlfriend at an Italian restaurant. It was her birthday. I wanted to invite her to a special dinner. I had reserved a table beforehand.

At seven o''clock we arrived. The waiter gave us a seat by the window. The music was quiet. There were candles on the tables.

First the waiter brought us the menu. I ordered a red wine, my girlfriend a mineral water.

As a starter we ate bruschetta. Then I ordered spaghetti and my girlfriend a pizza. The portions were big, and everything tasted very good.

For dessert I had tiramisu. Then we also drank an espresso.

The meal cost 75 euros. I paid by card and gave the waiter ten euros as a tip. My girlfriend was very happy.',
  key_vocabulary = '[{"de":"das Restaurant, -s","en":"restaurant"},{"de":"der Kellner, - / die Kellnerin, -nen","en":"waiter, waitress"},{"de":"reservieren","en":"to reserve"},{"de":"der Tisch, -e","en":"table"},{"de":"die Speisekarte, -n","en":"menu"},{"de":"bestellen","en":"to order"},{"de":"die Vorspeise, -n","en":"starter"},{"de":"die Portion, -en","en":"portion"},{"de":"schmecken","en":"to taste"},{"de":"der Nachtisch, -e","en":"dessert"},{"de":"bezahlen","en":"to pay"},{"de":"das Trinkgeld, -er","en":"tip"},{"de":"glücklich","en":"happy"}]'::jsonb,
  questions = '[{"question_de":"Warum sind die beiden ins Restaurant gegangen?","question_en":"Why did the two of them go to the restaurant?","answer_de":"Die Freundin hatte Geburtstag.","answer_en":"It was the girlfriend''s birthday."},{"question_de":"Wann sind die beiden im Restaurant angekommen?","question_en":"When did the two of them arrive at the restaurant?","answer_de":"Sie sind um sieben Uhr angekommen.","answer_en":"They arrived at seven o''clock."},{"question_de":"Was haben die beiden als Vorspeise gegessen?","question_en":"What did the two of them eat as a starter?","answer_de":"Sie haben Bruschetta gegessen.","answer_en":"They ate bruschetta."},{"question_de":"Was hat die Person zum Nachtisch genommen?","question_en":"What did the person have for dessert?","answer_de":"Sie hat Tiramisu genommen.","answer_en":"The person had tiramisu."},{"question_de":"Wie viel Trinkgeld hat die Person gegeben?","question_en":"How much tip did the person give?","answer_de":"Sie hat zehn Euro Trinkgeld gegeben.","answer_en":"The person gave ten euros as a tip."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person hat vorher einen Tisch reserviert.","statement_en":"The person had reserved a table beforehand.","answer":"richtig","explanation_de":"Im Text steht: Ich habe vorher einen Tisch reserviert."},{"type":"rf","statement_de":"Die beiden haben in einem griechischen Restaurant gegessen.","statement_en":"The two of them ate at a Greek restaurant.","answer":"falsch","explanation_de":"Im Text steht: Letzten Samstag habe ich mit meiner Freundin in einem italienischen Restaurant gegessen."},{"type":"rf","statement_de":"Der Kellner hat ihnen einen Platz am Fenster gegeben.","statement_en":"The waiter gave them a seat by the window.","answer":"richtig","explanation_de":"Im Text steht: Der Kellner hat uns einen Platz am Fenster gegeben."},{"type":"rf","statement_de":"Das Essen hat 75 Euro gekostet.","statement_en":"The meal cost 75 euros.","answer":"richtig","explanation_de":"Im Text steht: Das Essen hat 75 Euro gekostet."},{"type":"rf","statement_de":"Die Person hat bar bezahlt.","statement_en":"The person paid in cash.","answer":"falsch","explanation_de":"Im Text steht: Ich habe mit Karte bezahlt."},{"type":"choice","statement_de":"Was hat die Freundin gegessen? a) Spaghetti b) eine Pizza c) einen Salat","statement_en":"What did the girlfriend eat? a) spaghetti b) a pizza c) a salad","options":["a","b","c"],"answer":"b","explanation_de":"Im Text steht: Danach habe ich Spaghetti bestellt und meine Freundin eine Pizza."}]'::jsonb,
