UPDATE public.reading_lessons SET
  title_de = 'Ein Umzug nach Hamburg',
  title_en = 'A Move to Hamburg',
  content_de = 'Familie Weber hat zehn Jahre in Stuttgart gewohnt. Im März hat Frau Weber eine neue Stelle in Hamburg bekommen. Im Sommer ist die Familie umgezogen. Am Anfang wollten die Kinder nicht umziehen.

Der Umzug hat viel Arbeit gemacht. Zuerst haben die Webers eine Wohnung gesucht. Das war nicht leicht, denn in Hamburg sind die Mieten hoch. Nach sechs Wochen haben sie eine helle Wohnung in Eimsbüttel gefunden. Die Wohnung liegt im dritten Stock, und es gibt keinen Aufzug.

Dann haben alle geholfen. Herr Weber hat fünfzig Kartons gepackt. Die Kinder haben ihre Bücher eingepackt. Die Großeltern haben auf den Hund aufgepasst. Eine Firma hat die Möbel getragen.

Am Umzugstag ist der Lastwagen um sieben Uhr losgefahren.

In der neuen Wohnung hat Frau Weber die Küche eingeräumt. Herr Weber hat die Lampen aufgehängt. Die Nachbarn waren nett. Frau Schmidt hat der Familie einen Kuchen geschenkt.',
  content_en = 'The Weber family lived in Stuttgart for ten years. In March Mrs. Weber got a new job in Hamburg. In the summer the family moved. At first the children did not want to move.

The move was a lot of work. First the Webers looked for an apartment. That was not easy, because rents in Hamburg are high. After six weeks they found a bright apartment in Eimsbüttel. The apartment is on the third floor, and there is no lift.

Then everybody helped. Mr. Weber packed fifty boxes. The children packed their books. The grandparents looked after the dog. A company carried the furniture.

On moving day the truck set off at seven o''clock.

In the new apartment Mrs. Weber put away the kitchen things. Mr. Weber hung up the lamps. The neighbours were nice. Mrs. Schmidt gave the family a cake.',
  key_vocabulary = '[{"de":"der Umzug, ¨-e","en":"move, relocation"},{"de":"umziehen","en":"to move house"},{"de":"die Stelle, -n","en":"job, position"},{"de":"die Miete, -n","en":"rent"},{"de":"die Wohnung, -en","en":"apartment"},{"de":"hell","en":"bright"},{"de":"der Stock, Stockwerke","en":"floor, storey"},{"de":"der Aufzug, ¨-e","en":"lift, elevator"},{"de":"der Karton, -s","en":"cardboard box"},{"de":"einpacken","en":"to pack up"},{"de":"aufpassen (auf + Akk.)","en":"to look after"},{"de":"der Lastwagen, -","en":"truck"},{"de":"einräumen","en":"to put away, to tidy in"},{"de":"der Nachbar, -n / die Nachbarin, -nen","en":"neighbour"}]'::jsonb,
  questions = '[{"question_de":"Wann hat Frau Weber eine neue Stelle bekommen?","question_en":"When did Mrs. Weber get a new job?","answer_de":"Sie hat im März eine neue Stelle bekommen.","answer_en":"She got a new job in March."},{"question_de":"Warum war die Wohnungssuche nicht leicht?","question_en":"Why was looking for an apartment not easy?","answer_de":"In Hamburg sind die Mieten hoch.","answer_en":"Rents in Hamburg are high."},{"question_de":"Wer hat die Möbel getragen?","question_en":"Who carried the furniture?","answer_de":"Eine Firma hat die Möbel getragen.","answer_en":"A company carried the furniture."},{"question_de":"Was hat Frau Weber in der neuen Wohnung gemacht?","question_en":"What did Mrs. Weber do in the new apartment?","answer_de":"Sie hat die Küche eingeräumt.","answer_en":"She put away the kitchen things."},{"question_de":"Was hat Frau Schmidt der Familie geschenkt?","question_en":"What did Mrs. Schmidt give the family?","answer_de":"Sie hat der Familie einen Kuchen geschenkt.","answer_en":"She gave the family a cake."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Familie Weber hat zwanzig Jahre in Stuttgart gewohnt.","statement_en":"The Weber family lived in Stuttgart for twenty years.","answer":"falsch","explanation_de":"Im Text steht: Familie Weber hat zehn Jahre in Stuttgart gewohnt."},{"type":"rf","statement_de":"Die Familie ist im Sommer umgezogen.","statement_en":"The family moved in the summer.","answer":"richtig","explanation_de":"Im Text steht: Im Sommer ist die Familie umgezogen."},{"type":"rf","statement_de":"Die Familie hat die Wohnung nach zwei Wochen gefunden.","statement_en":"The family found the apartment after two weeks.","answer":"falsch","explanation_de":"Im Text steht: Nach sechs Wochen haben sie eine helle Wohnung in Eimsbüttel gefunden."},{"type":"rf","statement_de":"Die Wohnung liegt im ersten Stock.","statement_en":"The apartment is on the first floor.","answer":"falsch","explanation_de":"Im Text steht: Die Wohnung liegt im dritten Stock."},{"type":"rf","statement_de":"Die Großeltern haben auf den Hund aufgepasst.","statement_en":"The grandparents looked after the dog.","answer":"richtig","explanation_de":"Im Text steht: Die Großeltern haben auf den Hund aufgepasst."},{"type":"choice","statement_de":"Wie viele Kartons hat Herr Weber gepackt? a) fünfzig b) fünfzehn c) fünf","statement_en":"How many boxes did Mr. Weber pack? a) fifty b) fifteen c) five","options":["a","b","c"],"answer":"a","explanation_de":"Im Text steht: Herr Weber hat fünfzig Kartons gepackt."}]'::jsonb,
  word_count = 144,
  estimated_reading_time = 3
WHERE id = '41c5fb24-317d-428a-977d-0bc2baba885c'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Der Sportverein',
  title_en = 'The Sports Club',
  content_de = 'Lena kommt aus Spanien. Vor einem Jahr ist sie nach Köln gezogen. Am Anfang hat sie hier niemanden gekannt. Sie konnte damals auch noch nicht gut Deutsch.

Eine Kollegin hat ihr einen guten Tipp gegeben: „Geh zu einem Sportverein! Dort findest du schnell Freunde.“ Lena hat im Internet gesucht und einen Volleyballverein gefunden. Der Verein ist in ihrem Stadtteil.

Zuerst hat Lena ein Probetraining gemacht. Das war kostenlos. Das Training hat ihr sofort gefallen. Dann hat sie ein Formular ausgefüllt. Jetzt ist sie Mitglied. Der Beitrag kostet nur zwölf Euro im Monat.

Lena trainiert zweimal pro Woche, dienstags und donnerstags von 19 bis 21 Uhr. Am Wochenende spielt ihre Mannschaft manchmal gegen Teams aus der Region.

Im Sommer hat der Verein ein Grillfest gemacht. Die Trainerin bekommt kein Geld für ihre Arbeit. Lena sagt: „Der Verein ist für mich wie eine zweite Familie.“',
  content_en = 'Lena comes from Spain. A year ago she moved to Cologne. At the beginning she did not know anybody here. Back then her German was not good yet.

A colleague gave her a good tip: "Go to a sports club! You will find friends there quickly." Lena searched on the internet and found a volleyball club. The club is in her district.

First Lena did a trial training session. It was free. She liked the training straight away. Then she filled in a form. Now she is a member. The fee is only twelve euros a month.

Lena trains twice a week, on Tuesdays and Thursdays from 7 to 9 p.m. At the weekend her team sometimes plays against teams from the region.

In the summer the club had a barbecue party. The coach does not get any money for her work. Lena says: "The club is like a second family for me."',
  key_vocabulary = '[{"de":"der Verein, -e","en":"club, association"},{"de":"das Mitglied, -er","en":"member"},{"de":"der Tipp, -s","en":"tip, piece of advice"},{"de":"der Stadtteil, -e","en":"district"},{"de":"das Probetraining, -s","en":"trial training session"},{"de":"kostenlos","en":"free of charge"},{"de":"das Training, -s","en":"training"},{"de":"das Formular, -e","en":"form"},{"de":"ausfüllen","en":"to fill in"},{"de":"der Beitrag, ¨-e","en":"membership fee"},{"de":"die Mannschaft, -en","en":"team"},{"de":"die Trainerin, -nen","en":"coach (female)"},{"de":"das Grillfest, -e","en":"barbecue party"}]'::jsonb,
  questions = '[{"question_de":"Woher kommt Lena?","question_en":"Where does Lena come from?","answer_de":"Lena kommt aus Spanien.","answer_en":"Lena comes from Spain."},{"question_de":"Wo hat Lena einen Verein gesucht?","question_en":"Where did Lena look for a club?","answer_de":"Sie hat im Internet gesucht.","answer_en":"She looked on the internet."},{"question_de":"Was hat Lena nach dem Probetraining gemacht?","question_en":"What did Lena do after the trial training session?","answer_de":"Sie hat ein Formular ausgefüllt.","answer_en":"She filled in a form."},{"question_de":"Gegen wen spielt die Mannschaft am Wochenende?","question_en":"Who does the team play against at the weekend?","answer_de":"Sie spielt manchmal gegen Teams aus der Region.","answer_en":"It sometimes plays against teams from the region."},{"question_de":"Bekommt die Trainerin Geld für ihre Arbeit?","question_en":"Does the coach get money for her work?","answer_de":"Nein, sie bekommt kein Geld für ihre Arbeit.","answer_en":"No, the coach does not get any money for her work."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Lena spielt Volleyball.","statement_en":"Lena plays volleyball.","answer":"richtig","explanation_de":"Im Text steht: Lena hat im Internet gesucht und einen Volleyballverein gefunden. ... Jetzt ist sie Mitglied."},{"type":"rf","statement_de":"Das Probetraining war kostenlos.","statement_en":"The trial training session was free.","answer":"richtig","explanation_de":"Im Text steht: Zuerst hat Lena ein Probetraining gemacht. Das war kostenlos."},{"type":"rf","statement_de":"Der Beitrag kostet zwanzig Euro im Monat.","statement_en":"The fee is twenty euros a month.","answer":"falsch","explanation_de":"Im Text steht: Der Beitrag kostet nur zwölf Euro im Monat."},{"type":"rf","statement_de":"Eine Kollegin hat Lena den Tipp gegeben.","statement_en":"A colleague gave Lena the tip.","answer":"richtig","explanation_de":"Im Text steht: Eine Kollegin hat ihr einen guten Tipp gegeben."},{"type":"rf","statement_de":"Der Verein hat im Winter ein Grillfest gemacht.","statement_en":"The club had a barbecue party in winter.","answer":"falsch","explanation_de":"Im Text steht: Im Sommer hat der Verein ein Grillfest gemacht."},{"type":"choice","statement_de":"Wie oft trainiert Lena? a) einmal pro Woche b) dreimal pro Woche c) zweimal pro Woche","statement_en":"How often does Lena train? a) once a week b) three times a week c) twice a week","options":["a","b","c"],"answer":"c","explanation_de":"Im Text steht: Lena trainiert zweimal pro Woche, dienstags und donnerstags."}]'::jsonb,
  word_count = 143,
  estimated_reading_time = 3
WHERE id = '671fefe0-de8f-4db2-957d-7616be5e35d2'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Ein Besuch auf dem Wochenmarkt',
  title_en = 'A Visit to the Weekly Market',
  content_de = 'Samstagmorgen in Freiburg. Auf dem Platz vor dem Münster ist Wochenmarkt. Die ersten Stände öffnen schon um halb acht.

Jonas geht fast jeden Samstag mit seiner Tochter Emma zum Markt. Sie fahren mit der Straßenbahn in die Stadt, denn Parkplätze sind teuer.

Zuerst gehen die beiden zu einem Gemüsestand. Der Bauer kommt aus einem Dorf bei Freiburg. „Was darf es sein?“, fragt er. Jonas kauft ein Kilo Tomaten und einen Salat. Am Obststand nebenan probiert Emma eine Erdbeere. Danach kaufen die beiden noch Eier und ein Brot.

Auf dem Markt bezahlt man oft bar, denn viele Stände nehmen keine Karte. Die Preise sind manchmal höher als im Supermarkt. Aber die Waren kommen direkt vom Bauernhof.

Zum Schluss kauft Jonas seiner Tochter eine Brezel. Dann fahren die beiden nach Hause und kochen zusammen.',
  content_en = 'Saturday morning in Freiburg. On the square in front of the cathedral there is a weekly market. The first stalls open as early as half past seven.

Almost every Saturday Jonas goes to the market with his daughter Emma. They take the tram into town, because parking spaces are expensive.

First the two of them go to a vegetable stall. The farmer comes from a village near Freiburg. "What can I get you?" he asks. Jonas buys a kilo of tomatoes and a lettuce. At the fruit stall next to it Emma tries a strawberry. After that the two of them also buy eggs and a loaf of bread.

At the market people often pay in cash, because many stalls do not take cards. The prices are sometimes higher than at the supermarket. But the goods come straight from the farm.

Finally Jonas buys his daughter a pretzel. Then the two of them go home and cook together.',
  key_vocabulary = '[{"de":"der Wochenmarkt, ¨-e","en":"weekly market"},{"de":"der Stand, ¨-e","en":"stall, stand"},{"de":"die Straßenbahn, -en","en":"tram"},{"de":"der Parkplatz, ¨-e","en":"parking space"},{"de":"der Gemüsestand, ¨-e","en":"vegetable stall"},{"de":"der Bauer, -n","en":"farmer"},{"de":"das Dorf, ¨-er","en":"village"},{"de":"probieren","en":"to try, to taste"},{"de":"die Erdbeere, -n","en":"strawberry"},{"de":"bar bezahlen","en":"to pay in cash"},{"de":"der Preis, -e","en":"price"},{"de":"die Ware, -n","en":"goods"},{"de":"der Bauernhof, ¨-e","en":"farm"},{"de":"die Brezel, -n","en":"pretzel"}]'::jsonb,
  questions = '[{"question_de":"Wie oft geht Jonas zum Markt?","question_en":"How often does Jonas go to the market?","answer_de":"Er geht fast jeden Samstag zum Markt.","answer_en":"He goes to the market almost every Saturday."},{"question_de":"Was kauft Jonas am Gemüsestand?","question_en":"What does Jonas buy at the vegetable stall?","answer_de":"Er kauft ein Kilo Tomaten und einen Salat.","answer_en":"He buys a kilo of tomatoes and a lettuce."},{"question_de":"Was probiert Emma am Obststand?","question_en":"What does Emma try at the fruit stall?","answer_de":"Sie probiert eine Erdbeere.","answer_en":"She tries a strawberry."},{"question_de":"Woher kommen die Waren?","question_en":"Where do the goods come from?","answer_de":"Die Waren kommen direkt vom Bauernhof.","answer_en":"The goods come straight from the farm."},{"question_de":"Was machen Jonas und Emma zu Hause?","question_en":"What do Jonas and Emma do at home?","answer_de":"Sie kochen zusammen.","answer_en":"They cook together."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Der Markt ist auf dem Platz vor dem Bahnhof.","statement_en":"The market is on the square in front of the station.","answer":"falsch","explanation_de":"Im Text steht: Auf dem Platz vor dem Münster ist Wochenmarkt."},{"type":"rf","statement_de":"Die ersten Stände öffnen um halb neun.","statement_en":"The first stalls open at half past eight.","answer":"falsch","explanation_de":"Im Text steht: Die ersten Stände öffnen schon um halb acht."},{"type":"rf","statement_de":"Jonas und Emma fahren mit der Straßenbahn in die Stadt.","statement_en":"Jonas and Emma take the tram into town.","answer":"richtig","explanation_de":"Im Text steht: Sie fahren mit der Straßenbahn in die Stadt."},{"type":"rf","statement_de":"Auf dem Markt bezahlt man immer mit Karte.","statement_en":"At the market people always pay by card.","answer":"falsch","explanation_de":"Im Text steht: Auf dem Markt bezahlt man oft bar, denn viele Stände nehmen keine Karte."},{"type":"rf","statement_de":"Der Bauer kommt aus einem Dorf bei Freiburg.","statement_en":"The farmer comes from a village near Freiburg.","answer":"richtig","explanation_de":"Im Text steht: Der Bauer kommt aus einem Dorf bei Freiburg."},{"type":"choice","statement_de":"Was kauft Jonas zum Schluss für Emma? a) eine Erdbeere b) eine Brezel c) ein Brot","statement_en":"What does Jonas buy for Emma at the end? a) a strawberry b) a pretzel c) bread","options":["a","b","c"],"answer":"b","explanation_de":"Im Text steht: Zum Schluss kauft Jonas seiner Tochter eine Brezel."}]'::jsonb,
  word_count = 132,
  estimated_reading_time = 2
WHERE id = '5fe05477-4bb9-4814-bd73-049713182fbc'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

