INSERT INTO public.reading_lessons
  (level, title_de, title_en, topic, content_de, content_en, key_vocabulary, questions, checks, word_count, difficulty, estimated_reading_time, order_index)
SELECT
  'a2.1', 'Lesen Teil 1: Ein Zeitungstext (wie in der Prüfung)', 'Reading Part 1: A newspaper text (exam-style)', 'Prüfungsformat',
  'Lies den Text. Wähle die richtige Antwort: a, b oder c.

Stadtfest in Lindau: drei Tage Musik und Essen

Am Wochenende gibt es wieder das große Stadtfest in Lindau. Es beginnt am Freitag um 16 Uhr und endet am Sonntag um 22 Uhr.

Auf dem Marktplatz spielen zwanzig Bands. Fast alle Konzerte am Abend sind kostenlos. Nur für das Konzert am Samstagabend braucht man eine Karte. Sie kostet acht Euro.

Es gibt auch viele Stände mit Essen und Getränken aus der Region. Das Stadtfest gibt es schon seit dreißig Jahren.

Für die Kinder gibt es einen Platz vor dem Rathaus. Dort können sie von 11 bis 18 Uhr spielen und malen.

Am Wochenende darf man nicht mit dem Auto ins Zentrum fahren. Bitte kommen Sie mit dem Bus. Die Stadt Lindau schreibt: „Kommen Sie vorbei und feiern Sie mit uns!“', 'Read the text. Choose the correct answer: a, b or c.

Town festival in Lindau: three days of music and food

This weekend there is the big town festival in Lindau again. It starts on Friday at 4 p.m. and ends on Sunday at 10 p.m.

Twenty bands play on the market square. Almost all evening concerts are free. Only for the concert on Saturday evening do you need a ticket. It costs eight euros.

There are also many stalls with food and drinks from the region. The town festival has existed for thirty years.

For the children there is a square in front of the town hall. They can play and paint there from 11 a.m. to 6 p.m.

At the weekend you are not allowed to drive into the centre by car. Please come by bus. The town of Lindau writes: "Come along and celebrate with us!"',
  '[{"de":"das Stadtfest, -e","en":"town festival"},{"de":"beginnen","en":"to begin"},{"de":"enden","en":"to end"},{"de":"der Marktplatz, ¨-e","en":"market square"},{"de":"das Konzert, -e","en":"concert"},{"de":"kostenlos","en":"free of charge"},{"de":"die Karte, -n","en":"ticket"},{"de":"der Stand, ¨-e","en":"stall, stand"},{"de":"das Rathaus, ¨-er","en":"town hall"},{"de":"feiern","en":"to celebrate"}]'::jsonb, '[{"question_de":"Was gibt es am Wochenende in Lindau?","question_en":"What is happening in Lindau this weekend?","answer_de":"In Lindau gibt es das große Stadtfest.","answer_en":"In Lindau there is the big town festival."},{"question_de":"Was kann man an den Ständen kaufen?","question_en":"What can you buy at the stalls?","answer_de":"Man kann Essen und Getränke aus der Region kaufen.","answer_en":"You can buy food and drinks from the region."},{"question_de":"Wie soll man zum Stadtfest kommen?","question_en":"How should you come to the town festival?","answer_de":"Man soll mit dem Bus kommen.","answer_en":"You should come by bus."}]'::jsonb, '[{"type":"choice","statement_de":"Wann beginnt das Stadtfest? a) am Freitag b) am Samstag c) am Sonntag","statement_en":"When does the town festival start? a) on Friday b) on Saturday c) on Sunday","options":["a","b","c"],"answer":"a","explanation_de":"Im Text steht: Es beginnt am Freitag um 16 Uhr."},{"type":"choice","statement_de":"Wo spielen die Bands? a) vor dem Rathaus b) auf dem Marktplatz c) am Bahnhof","statement_en":"Where do the bands play? a) in front of the town hall b) on the market square c) at the station","options":["a","b","c"],"answer":"b","explanation_de":"Im Text steht: Auf dem Marktplatz spielen zwanzig Bands."},{"type":"choice","statement_de":"Was kostet die Karte am Samstagabend? a) achtzehn Euro b) nichts c) acht Euro","statement_en":"What does the ticket for Saturday evening cost? a) eighteen euros b) nothing c) eight euros","options":["a","b","c"],"answer":"c","explanation_de":"Im Text steht: Sie kostet acht Euro."},{"type":"choice","statement_de":"Was können die Kinder vor dem Rathaus machen? a) spielen und malen b) Musik machen c) Essen kaufen","statement_en":"What can the children do in front of the town hall? a) play and paint b) make music c) buy food","options":["a","b","c"],"answer":"a","explanation_de":"Im Text steht: Dort können sie von 11 bis 18 Uhr spielen und malen."},{"type":"choice","statement_de":"Wie lange gibt es das Stadtfest schon? a) seit dreizehn Jahren b) seit zwanzig Jahren c) seit dreißig Jahren","statement_en":"How long has the town festival existed? a) for thirteen years b) for twenty years c) for thirty years","options":["a","b","c"],"answer":"c","explanation_de":"Im Text steht: Das Stadtfest gibt es schon seit dreißig Jahren."}]'::jsonb,
  140, 2, 3, 9
WHERE NOT EXISTS (
  SELECT 1 FROM public.reading_lessons WHERE level = 'a2.1' AND title_de = 'Lesen Teil 1: Ein Zeitungstext (wie in der Prüfung)'
);

INSERT INTO public.reading_lessons
  (level, title_de, title_en, topic, content_de, content_en, key_vocabulary, questions, checks, word_count, difficulty, estimated_reading_time, order_index)
SELECT
  'a2.1', 'Lesen Teil 3: Eine E-Mail (wie in der Prüfung)', 'Reading Part 3: An email (exam-style)', 'Prüfungsformat',
  'Lies die E-Mail. Wähle die richtige Antwort: a, b oder c.

Von: m.hoffmann@sprachschule-nord.de
An: kurs-a2@sprachschule-nord.de
Betreff: Ihr Deutschkurs ab Oktober

Sehr geehrte Damen und Herren,

Ihr Kurs A2.2 beginnt am Dienstag, 6. Oktober. Der Unterricht ist immer dienstags und donnerstags von 18 bis 20 Uhr. Wir arbeiten in Raum 12 im zweiten Stock. Im Kurs sind zwölf Personen.

Bitte bringen Sie das Buch „Deutsch im Alltag“ mit. Sie können es in der Schule für 22 Euro kaufen.

Am ersten Abend gibt es einen kleinen Test. Der Test ist nicht schwer. Am 3. November gibt es keinen Unterricht. Bitte kommen Sie immer pünktlich zum Unterricht.

Der Kurs kostet 180 Euro. Bitte bezahlen Sie bis zum 30. September.

Haben Sie noch Fragen? Rufen Sie mich an: 0451 998877.

Mit freundlichen Grüßen
Maria Hoffmann', 'Read the email. Choose the correct answer: a, b or c.

From: m.hoffmann@sprachschule-nord.de
To: kurs-a2@sprachschule-nord.de
Subject: Your German course from October

Dear Sir or Madam,

Your course A2.2 starts on Tuesday, 6 October. The lessons are always on Tuesdays and Thursdays from 6 to 8 p.m. We work in room 12 on the second floor. The course has twelve people in it.

Please bring the book "Deutsch im Alltag" with you. You can buy it at the school for 22 euros.

On the first evening there is a small test. The test is not difficult. On 3 November there are no lessons. Please always come to the lesson on time.

The course costs 180 euros. Please pay by 30 September.

Do you have any questions? Call me: 0451 998877.

Kind regards
Maria Hoffmann',
